00141     public static function getItemPowerShell($caption, $glyph, $id = null, $title = null, $initDir = null, $command = null)
00142     {
00143         global $bearsamppTools;
00144 
00145         if ($title === null) {
00146             $title = $bearsamppTools->getPowerShell()->getTabTitleDefault();
00147         }
00148 
00149         // Launch pwsh.exe directly — no powershell.bat wrapper, no cmd.exe, no flashing window.
00150         // Registry font settings are pre-written during reload by TplPowerShell::process().
00151         $pwsh = $bearsamppTools->getPowerShell()->getExe();
00152         $profilePath = Path::formatWindowsPath($bearsamppTools->getPowerShell()->getConf());
00153 
00154         // Build the inline PowerShell -Command string.
00155         // Single-quoted strings are used for paths/titles so backslashes need no escaping.
00156         // $Host and [Console] are PowerShell syntax; no shell variable expansion occurs here
00157         // because Aestan calls CreateProcess directly (no cmd.exe intermediary).
00158         $psCommand = '[Console]::OutputEncoding=[System.Text.Encoding]::UTF8;' .
00159                      '[Console]::InputEncoding=[System.Text.Encoding]::UTF8;' .
00160                      '$Host.UI.RawUI.WindowTitle=\'' . $title . '\';';
00161 
00162         if ($command !== null) {
00163             $psCommand .= $command . ';';
00164         }
00165 
00166         $psCommand .= '. \'' . $profilePath . '\'';
00167 
00168         // Build pwsh.exe argument string using Aestan's "" escaping for embedded double quotes.
00169         // -WorkingDirectory sets the initial directory (PowerShell 7+), avoiding Set-Location.
00170         $params = '-NoExit -NoProfile';
00171         if ($initDir !== null) {
00172             $params .= ' -WorkingDirectory ""' . $initDir . '""';
00173         }
00174         $params .= ' -Command ""' . $psCommand . '""';
00175 
00176         return self::getItemExe($caption, $pwsh, $glyph, $params);
00177     }
