00266     private static function getActionService($service, $action, $item = false)
00267     {
00268         global $bearsamppLang;
00269         $result = 'Action: ' . $action;
00270 
00271         if ($service != null) {
00272             $result = 'Action: service; ' .
00273                 'Service: ' . $service . '; ' .
00274                 'ServiceAction: ' . $action;
00275         }
00276 
00277         if ($item) {
00278             $result = 'Type: item; ' . $result;
00279             if ($action == self::SERVICE_START) {
00280                 $result .= '; Caption: "' . $bearsamppLang->getValue(Lang::MENU_START_SERVICE) . '"' .
00281                     '; Glyph: ' . self::GLYPH_START;
00282             } elseif ($action == self::SERVICE_STOP) {
00283                 $result .= '; Caption: "' . $bearsamppLang->getValue(Lang::MENU_STOP_SERVICE) . '"' .
00284                     '; Glyph: ' . self::GLYPH_STOP;
00285             } elseif ($action == self::SERVICE_RESTART) {
00286                 $result .= '; Caption: "' . $bearsamppLang->getValue(Lang::MENU_RESTART_SERVICE) . '"' .
00287                     '; Glyph: ' . self::GLYPH_RELOAD;
00288             }
00289         } elseif ($action != self::SERVICES_CLOSE) {
00290             $result .= '; Flags: ignoreerrors waituntilterminated';
00291         }
00292 
00293         return $result;
00294     }
